// Extraer execution_id y guardarlo en variable
const executionId = items[0].json.execution_id;

// Crear item con solo execution_id para continuar
return [{
  json: {
    execution_id: executionId
  }
}];

// CORREGIDO: items[0] tiene execution_id, items[1..n] tienen proyectos
const executionId = items[0].json.execution_id;

// Los proyectos vienen en items individuales, no en un array
const projectItems = items.slice(1);
const activeProjects = [];

// Filtrar proyectos no archivados
for (const item of projectItems) {
  if (item.json && !item.json.archived) {
    activeProjects.push(item.json);
  }
}

// 1. Item para actualizar execution_log
const updateExecution = {
  json: {
    execution_id: executionId,
    total_projects_scanned: activeProjects.length,
    end_time: new Date().toISOString(),
    status: 'success'
  }
};

// 2. Items para upsert en gitlab_projects
const projectData = activeProjects.map(project => ({
  json: {
    gitlab_project_id: project.id,
    project_name: project.name || 'Unnamed',
    path_with_namespace: project.path_with_namespace || '',
    web_url: project.web_url || '',
    last_activity_at: project.last_activity_at || null,
    created_at: project.created_at || null,
    updated_at: new Date().toISOString(),
    execution_id: executionId
  }
}));

// Devolver primero el update, luego los proyectos
const result = [updateExecution];
return result.concat(projectData);

// CORREGIDO: items[0] es update, items[1..n] son proyectos insertados
const executionId = items[0].json.execution_id; // Del update
const projectItems = items.slice(1); // Los proyectos upsertados
const results = [];
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

for (const projectItem of projectItems) {
  const project = projectItem.json;

  results.push({
    json: {
      execution_id: executionId,
      project_id: project.gitlab_project_id || project.project_id,
      commits_url: `http://172.24.7.110/api/v4/projects/${project.gitlab_project_id || project.project_id}/repository/commits?since=${yesterday.toISOString()}&per_page=100`,
      branches_url: `http://172.24.7.110/api/v4/projects/${project.gitlab_project_id || project.project_id}/repository/branches`
    }
  });
}

return results;

// CORREGIDO: items[0] = datos proyecto + execution_id, items[1] = commits, items[2] = branches
const executionId = items[0].json.execution_id;
const projectId = items[0].json.project_id;
const commits = items[1] ? items[1].json : [];
const branches = items[2] ? items[2].json : [];
const today = new Date().toISOString().split('T')[0];

const metrics = {
  authors: {},
  branches: {},
  hours: {},
  lines: { added: 0, deleted: 0 }
};

// Procesar commits
for (const commit of commits) {
  const authorName = commit.author_name || 'Unknown';
  const authorEmail = commit.author_email || 'unknown@example.com';
  const commitDate = new Date(commit.committed_date || commit.created_at);
  const hour = commitDate.getUTCHours();
  const weekDay = commitDate.getUTCDay();
  const branchName = commit.ref_name || 'main';

  // Autor
  const authorKey = `${authorName}_${authorEmail}`;
  if (!metrics.authors[authorKey]) {
    metrics.authors[authorKey] = {
      name: authorName,
      email: authorEmail,
      count: 0
    };
  }
  metrics.authors[authorKey].count++;

  // Rama
  if (!metrics.branches[branchName]) {
    metrics.branches[branchName] = 0;
  }
  metrics.branches[branchName]++;

  // Hora
  const hourKey = `${weekDay}_${hour}`;
  if (!metrics.hours[hourKey]) {
    metrics.hours[hourKey] = {
      week_day: weekDay,
      hour_of_day: hour,
      count: 0
    };
  }
  metrics.hours[hourKey].count++;

  // Líneas
  if (commit.stats) {
    metrics.lines.added += commit.stats.additions || 0;
    metrics.lines.deleted += commit.stats.deletions || 0;
  }
}

// Preparar salida
const output = [];

// 1. commit_metrics_author
for (const author of Object.values(metrics.authors)) {
  output.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      author_name: author.name,
      author_email: author.email,
      commit_count: author.count,
      metric_date: today
    }
  });
}

// 2. commit_metrics_branch
for (const [branchName, count] of Object.entries(metrics.branches)) {
  output.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      branch_name: branchName,
      commit_count: count,
      metric_date: today
    }
  });
}

// 3. code_line_metrics
if (metrics.lines.added > 0 || metrics.lines.deleted > 0) {
  output.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      total_lines: metrics.lines.added + metrics.lines.deleted,
      added_lines: metrics.lines.added,
      deleted_lines: metrics.lines.deleted,
      metric_date: today
    }
  });
}

// 4. commit_frequency
for (const hourData of Object.values(metrics.hours)) {
  output.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      week_day: hourData.week_day,
      hour_of_day: hourData.hour_of_day,
      commit_count: hourData.count,
      metric_date: today
    }
  });
}

return output;
